const request = $('Webhook-PostMortem').item.json;
const expectedKey = $env.NINF_N8N_WEBHOOK_API_KEY;
const receivedKey = request.headers?.['x-ness-webhook-key'];
if (typeof expectedKey !== 'string' || expectedKey.length < 32 || receivedKey !== expectedKey) {
  throw new Error('Unauthorized webhook request');
}
const body = request.body;
if (!body || typeof body !== 'object' || Array.isArray(body)) {
  throw new Error('Invalid postmortem payload');
}
const field = (value, fallback, maxLength = 2000) => {
  if (typeof value !== 'string' && typeof value !== 'number') return fallback;
  return String(value).replace(/[\u0000-\u001f\u007f]/g, ' ').trim().slice(0, maxLength) || fallback;
};
const escapeHtml = (value) => String(value).replace(/[&<>\"']/g, (char) => ({
  '&': '&amp;', '<': '&lt;', '>': '&gt;', '\"': '&quot;', "'": '&#39;'
}[char]));
const list = (value) => Array.isArray(value)
  ? value.slice(0, 20).map((item) => field(item, '', 500)).filter(Boolean)
  : [];
const customerName = field(body.customer_name, 'Ness', 160);
const hostName = field(body.host_name, 'N/A', 160);
const summary = field(body.summary, 'Sem resumo.');
const rootCause = field(body.root_cause, 'Sem causa raiz.');
const actions = list(body.corrective_actions).join('\n- ') || 'Nenhuma ação informada.';
const blast = list(body.blast_radius).join(', ') || 'Não informado.';
const fingerprint = field(body.incident_fingerprint, 'N/A', 160);
const emailSubject = 'Re: [NOC-ALERT] ' + customerName + ' | Host: ' + hostName + ' | Fingerprint: ' + fingerprint;
const emailHtml = '<p><strong>📝 ANÁLISE DE CAUSA RAIZ (RCA) NOC 📝</strong></p>\n' +
  '<p><strong>Cliente:</strong> ' + escapeHtml(customerName) + '</p>\n' +
  '<p><strong>Equipamento:</strong> ' + escapeHtml(hostName) + '</p><hr/>\n' +
  '<p><strong>Resumo:</strong> ' + escapeHtml(summary) + '</p>\n' +
  '<p><strong>Causa Raiz:</strong> ' + escapeHtml(rootCause) + '</p>\n' +
  '<p><strong>Ações Corretivas:</strong><br/>- ' + escapeHtml(actions).replace(/\n/g, '<br/>- ') + '</p>\n' +
  '<p><strong>Raio de Impacto:</strong> ' + escapeHtml(blast) + '</p><hr/>\n' +
  '<p><small>Fingerprint: ' + escapeHtml(fingerprint) + '</small></p>';
const whatsappText = '📝 *ANÁLISE DE CAUSA RAIZ (RCA) NOC* 📝\n\n' +
  '*Cliente:* ' + customerName + '\n*Equipamento:* ' + hostName + '\n' +
  '*Resumo:* ' + summary + '\n*Causa Raiz:* ' + rootCause + '\n\n' +
  '*Ações Corretivas*:\n- ' + actions + '\n\n*Raio de Impacto:* ' + blast;
return {
  "options": { "delay": 1200, "presence": "composing" },
  "text": whatsappText,
  "emailSubject": emailSubject,
  "emailHtml": emailHtml
};
